PLAN_B64=''
AUTH_B64=''
PLAN_SHA='3f2038b9d90fecf727e24f901703df88d7b5b4f8d9bb2005a2b68aa5f660addf'
import base64,datetime as dt,hashlib,json,os,pathlib,platform,signal,socket,stat,subprocess,sys
def now():return dt.datetime.now(dt.timezone.utc)
def write(path,value):
    with path.open('x',encoding='utf-8') as f:json.dump(value,f,indent=2);f.write('\n')
def workers():
    result=[]
    for p in pathlib.Path('/proc').glob('[0-9]*/comm'):
        try:
            if p.read_text().strip()=='Runner.Worker':result.append(int(p.parent.name))
        except (FileNotFoundError,ProcessLookupError):pass
    return result
def check_idle():
    assert not workers(),'RUNNER_WORKER_ACTIVE'
    p=subprocess.run(['podman','ps','-a','--format','json'],capture_output=True,text=True,timeout=10)
    assert p.returncode==0 and json.loads(p.stdout)==[],'CONTAINERS_EXIST'
os.umask(0o077)
assert socket.gethostname()=='cicd-runner01' and os.getuid()==1000 and platform.machine()=='x86_64','WRONG_HOST'
home=pathlib.Path('/home/server01_cicd-runner');bundle=home/'FDS_D03_Preparation_192c5ab04a5e'
plan_raw=base64.b64decode(PLAN_B64);auth_raw=base64.b64decode(AUTH_B64)
plan=json.loads(plan_raw);auth=json.loads(auth_raw)
assert plan['run']=='202610142110' and hashlib.sha256(plan_raw).hexdigest()==PLAN_SHA
assert auth['approved'] is True and auth['runner_exclusive'] is True and auth['lab_db_image_accepted'] is True and auth['plan_sha256']==PLAN_SHA
deadline=dt.datetime.fromisoformat(auth['start_before']);assert now()<deadline
sys.path.insert(0,str(bundle/'source/tools/regression'))
import d03_lab
assert d03_lab.make_plan(plan['run'])==plan
for line in (bundle/'SHA256SUMS').read_text().splitlines():
    sha,rel=line.split('  ',1);p=bundle/rel
    assert p.resolve().is_relative_to(bundle) and not p.is_symlink() and hashlib.sha256(p.read_bytes()).hexdigest()==sha
check_idle()
out=home/'FDS_D03_Supply_202610142110';out.mkdir(mode=0o700)
result={'status':'STARTED','started_at_utc':now().isoformat(),'plan_sha256':PLAN_SHA,'runtime_started':False,'operations':[]}
write(out/'intent.json',result)
decisions=home/'FDS_D03_Decisions_202610142110';decisions.mkdir(mode=0o700)
with (decisions/'plan.json').open('xb') as f:f.write(plan_raw)
with (decisions/'authorization.json').open('xb') as f:f.write(auth_raw)
def perform(label,argv,timeout=180):
    check_idle();remaining=(deadline-now()).total_seconds();assert remaining>5,'SUPPLY_WINDOW_EXPIRED'
    item=out/label;item.mkdir(mode=0o700)
    record={'argv':argv,'started_at_utc':now().isoformat()};write(item/'intent.json',record)
    with (item/'stdout.txt').open('xb') as stdout,(item/'stderr.txt').open('xb') as stderr:
        p=subprocess.Popen(argv,stdout=stdout,stderr=stderr,start_new_session=True)
        try:rc=p.wait(timeout=min(timeout,remaining-1))
        except subprocess.TimeoutExpired:
            os.killpg(p.pid,signal.SIGTERM)
            try:p.wait(timeout=5)
            except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait(timeout=5)
            rc=None;record['timed_out']=True
    record.update(rc=rc,finished_at_utc=now().isoformat(),stdout_sha256=hashlib.sha256((item/'stdout.txt').read_bytes()).hexdigest(),stderr_sha256=hashlib.sha256((item/'stderr.txt').read_bytes()).hexdigest())
    write(item/'receipt.json',record);result['operations'].append({'label':label,**record})
    assert rc==0,'SUPPLY_FAILED_'+label
def inspect(image):
    p=subprocess.run(['podman','image','inspect',image],capture_output=True,timeout=15)
    assert p.returncode==0,'IMAGE_INSPECTION_FAILED'
    x=json.loads(p.stdout)[0]
    return {'Id':x['Id'],'RepoDigests':x.get('RepoDigests',[]),'Architecture':x.get('Architecture'),'Os':x.get('Os'),'User':x.get('Config',{}).get('User')}
try:
    base=home/'FDS_CICD_AppWorkflow.3_geu2kf/build-scan'
    sources=[('api',base/'transaction-api.oci.tar','ff3d145047f53b67f44b8a91994d7ab2b72998d9b276184b3c70a2148d52e3cf'),('engine',base/'fds-engine.oci.tar','319ab0af288d32a156feb1867193d3b7be0e663f2a17ee3efaa95aa505cd7031')]
    for label,p,expected in sources:
        st=p.lstat();assert stat.S_ISREG(st.st_mode) and st.st_uid==1000 and p.resolve().is_relative_to(home)
        h=hashlib.sha256()
        with p.open('rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
        assert h.hexdigest()==expected,'APP_ARCHIVE_CHANGED'
    for label,p,expected in sources:
        exists=subprocess.run(['podman','image','exists',plan['images'][label]],capture_output=True,timeout=10)
        assert exists.returncode in (0,1),'IMAGE_LOOKUP_FAILED'
        if exists.returncode==1:perform(label+'-load',['podman','load','--input',str(p)])
        else:result['operations'].append({'label':label,'status':'EXACT_IMAGE_ALREADY_PRESENT_NO_LOAD'})
        meta=inspect(plan['images'][label]);assert 'sha256:'+meta['Id'].removeprefix('sha256:')==plan['images'][label]
        write(out/(label+'-image.json'),meta)
    db=plan['images']['db']
    exists=subprocess.run(['podman','image','exists',db],capture_output=True,timeout=10)
    assert exists.returncode in (0,1),'DB_LOOKUP_FAILED'
    if exists.returncode==1:perform('db-pull',['podman','pull','--tls-verify=true',db])
    else:result['operations'].append({'label':'db','status':'EXACT_IMAGE_ALREADY_PRESENT_NO_PULL'})
    meta=inspect(db);assert db in meta['RepoDigests'] and meta['Architecture']=='amd64' and meta['Os']=='linux' and str(meta['User'])=='26'
    assert meta['Id'].removeprefix('sha256:')=='d0614d16e62078e0d1b6b55d86e834225988348162a0abb608944fa37a1091ef'
    write(out/'db-image.json',meta);check_idle();result['status']='SUPPLY_VERIFIED_RUNTIME_NOT_RUN'
except Exception as e:
    result.update(status='SUPPLY_STOP',error_type=type(e).__name__,error=str(e))
result['finished_at_utc']=now().isoformat();write(out/'result.json',result)
files=sorted(p for p in out.rglob('*') if p.is_file())
(out/'SHA256SUMS').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.relative_to(out).as_posix()+'\n' for p in files))
